totalTime() {
    // If there are no tasks, return 0
    if (this.tasks.size === 0) {
        return 0;
    }

    // Calculate the maximum time to complete all tasks in parallel
    // This is the critical path algorithm - find the longest path in the DAG

    // For each task, we track the maximum time to complete it
    const maxTimeToComplete = new Map();

    // Initialize with task durations
    for (const [id, duration] of this.tasks) {
        maxTimeToComplete.set(id, duration);
    }

    // Process tasks in topological order
    const orderedTasks = this.order();

    // For each task in topological order, update the max time for its dependents
    for (const taskId of orderedTasks) {
        const taskDuration = this.tasks.get(taskId);
        const maxTimeForThisTask = maxTimeToComplete.get(taskId);

        // For each dependent task, update its max completion time
        // We need to find all tasks that depend on this task
        for (const [dependentId, dependencies] of this.dependencies) {
            if (dependencies.has(taskId)) {
                // The time to complete the dependent task is the max of:
                // 1. Current max time for dependent task
                // 2. Time to complete this task + duration of this task
                const newTime = maxTimeForThisTask + taskDuration;
                const currentMaxTime = maxTimeToComplete.get(dependentId);
                maxTimeToComplete.set(dependentId, Math.max(currentMaxTime, newTime));
            }
        }
    }

    // The total time is the maximum time among all tasks
    let maxTime = 0;
    for (const time of maxTimeToComplete.values()) {
        maxTime = Math.max(maxTime, time);
    }

    return maxTime;
}

